"""Second-unit visual selections; rerunnable without duplicating records."""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[1]; a=json.loads((R/'selection.json').read_text());a=[s for s in a if s['chapter']!='第二单元 空气和氧气']
chapter='第二单元 空气和氧气';topic='课题1 我们周围的空气'
def add(name,regions,detail=None,notes=None):
 s=dict(chapter=chapter,topic=topic,name=name,regions=regions)
 if detail is not None:s['detail']=detail
 if notes:s['notes']=notes
 a.append(s)
add('空气组成的实验研究',[[37,285,470,185,520],[38,50,148,60,350]],detail='二百多年前，法国化学家拉瓦锡（如图2-1）研究了空气的成分（如图2-2）。他把少量汞放在密闭的容器里连续加热12天，发现有一部分银白色的液态汞变成红色粉末，同时容器里空气的体积减小了。他研究了容器里的剩余气体，发现这部分气体既不能供给呼吸，也不能支持燃烧。他认为这些气体全部是氮气（氮气的化学符号是N₂）。\n\n拉瓦锡又把汞表面生成的红色粉末收集起来，放在另一个较小的容器里再加强热，得到了汞（化学符号Hg）和氧气（化学符号O₂），而且氧气的体积恰好等于密闭容器里所减小的体积。他把得到的氧气加到前一个容器里剩下的气体中，结果所得气体的性质与空气的完全一样。通过实验和分析，拉瓦锡得出了空气由氧气和氮气组成的结论。',notes=['保留历史实验的必要情境和原结论，不以现代成分修订原实验叙述。'])
add('空气各成分的体积含量',[[38,266,315,60,350]],detail='通过实验测定，空气的成分按体积计算，大约是：氮气78%、氧气21%、稀有气体0.94%、二氧化碳0.04%、其他气体0.02%（如图2-3）。')
add('探究空气中氧气含量',[[38,368,620,60,350]],detail='仿照拉瓦锡实验的原理，我们可以探究空气中氧气的含量。例如，红磷（化学符号P）与空气中的氧气反应，生成一种叫作五氧化二磷（化学符号P₂O₅）的新物质，这一反应可以用文字表示如下：\n\n红磷 + 氧气 —点燃→ 五氧化二磷\n\n按图2-4所示的实验装置进行实验。在集气瓶内加入少量水，将水面上方空间分为5等份，并做好标记。用弹簧夹夹紧乳胶管。在燃烧匙内放入足量的红磷，用酒精灯加热，点燃红磷后立即伸入瓶中，并塞紧橡胶塞。待红磷熄灭并冷却至室温，打开弹簧夹，可以观察到烧杯中的水被吸入集气瓶，瓶内液面上升。请讨论并解释这个实验的原理。',notes=['原文未在此给出上升体积数值，不补写。'])
add('混合物与纯净物',[[39,56,215,185,520]],detail='像空气这样，由两种或两种以上的物质混合而成的物质叫作混合物，组成混合物的各种成分保持着它们各自的性质。氮气、氧气、二氧化碳等分别只由一种物质组成，它们都是纯净物。纯净物可以用化学符号来表示，如氮气可表示为N₂，氧气、二氧化碳可分别表示为O₂、CO₂。上面实验中使用的红磷（P）和生成的五氧化二磷（P₂O₅）也都是纯净物。')
add('测定空气中氧气含量的数字化实验',[[39,266,425,40,250],[39,297,400,255,520]],notes=['双栏按左栏后右栏顺序，连续句子先合并。'])
add('氧气的用途',[[40,140,190]])
add('氮气的性质和用途',[[40,392,465],[41,266,380]],detail='氮气具有广泛的用途（如图2-7），它是制造硝酸和氮肥的重要原料。由于氮气的化学性质不活泼，因此常被用作保护气，如焊接金属时用氮气作保护气，食品包装中充入氮气以防腐。医疗上可利用液氮进行冷冻治疗。超导材料在液氮的低温环境下能显示超导性能。\n\n根据日常生活经验及上面的讨论，填写下表，描述氮气的物理性质。\n\n|物质|颜色|气味|标准状况下的密度|熔点|沸点|是否易溶于水|\n|---|---|---|---|---|---|---|\n|氮气|||1.251 g/L|−210 ℃|−196 ℃||\n\n标准状况指的是温度为0 ℃和压强为101 kPa时的情况。\n\n红磷在氮气中不能燃烧等事实，说明氮气不支持燃烧。氮气的化学性质不如氧气的活泼。',notes=['空白性质不补写；保留标准状况脚注。'])
add('稀有气体的性质和用途',[[41,435,615,185,520]])
add('利用氩氦刀治疗肿瘤',[[42,213,315,60,280],[42,243,290,280,520]])
add('空气污染危害和大气保护',[[42,393,510]])
add('空气质量指数及分级',[[43,119,275,50,340],[43,355,440]],detail='空气质量指数日报的主要内容包括“空气质量指数”“首要污染物”“空气质量指数类别”等（如图2-9）。\n\n空气质量指数（air quality index，AQI）是依据常规监测的几种空气污染物浓度计算得到的。目前计入空气质量评价的主要污染物为：二氧化硫、一氧化碳、二氧化氮、可吸入颗粒物（粒径小于等于10 μm的颗粒物，PM₁₀）、细颗粒物（粒径小于等于2.5 μm的颗粒物，PM₂.₅）和臭氧等。根据空气质量指数可以对空气质量分级（如表2-1）。\n\n表2-1 空气质量分级标准\n\n|空气质量指数|0~50|51~100|101~150|151~200|201~300|>300|\n|---|---|---|---|---|---|---|\n|空气质量指数级别|一级|二级|三级|四级|五级|六级|\n|空气质量指数类别|优|良|轻度污染|中度污染|重度污染|严重污染|',notes=['剔除本栏评价性末段和未解调查任务，表格按视觉转录。'])
topic='课题2 氧气'
add('氧气的物理性质',[[45,182,280,185,520]],detail='在标准状况下，氧气的密度是1.429 g/L，比空气的密度（1.293 g/L）略大。氧气不易溶于水，在室温下，1 L水只能溶解约30 mL氧气。在压强为101 kPa时，氧气在−183.0 ℃变为淡蓝色液体，在−218.8 ℃变为淡蓝色固体。')
add('氧气支持燃烧与带火星木条检验',[[45,302,365]],notes=['实验2-1及原文明示木条复燃结论。'])
add('木炭在空气和氧气中燃烧',[[45,540,665,185,520],[46,50,225]],detail='【实验2-2】\n\n用坩埚钳夹取一小块木炭放在酒精灯火焰上加热，观察木炭在空气中燃烧的现象。然后把燃着的木炭插入充满氧气的集气瓶中（如图2-11），再观察木炭在氧气中燃烧的现象。比较木炭在空气和氧气中燃烧有什么不同。\n\n|实验内容|现象|\n|---|---|\n|木炭在空气中燃烧||\n|木炭在氧气中燃烧||\n\n木炭与氧气发生化学反应，生成了二氧化碳（CO₂）气体，并放出热量。这个反应可以表示如下：\n\n碳 + 氧气 —点燃→ 二氧化碳')
add('硫在空气和氧气中燃烧',[[46,245,545],[47,351,398]],detail='【实验2-3】\n\n在燃烧匙里放入少量硫，加热，直到发生燃烧，观察硫在空气中燃烧的现象。然后把盛有燃着的硫的燃烧匙插入充满氧气的集气瓶中（如图2-12），再观察硫在氧气中燃烧的现象。比较硫在空气和氧气中燃烧有什么不同。\n\n本实验由教师演示，应在通风橱中或排风设备下进行。\n\n|实验内容|现象|\n|---|---|\n|硫在空气中燃烧||\n|硫在氧气中燃烧||\n\n硫与氧气发生化学反应，生成了一种有刺激性气味的二氧化硫（SO₂）气体，并放出热量。这个反应可以表示如下：\n\n硫 + 氧气 —点燃→ 二氧化硫\n\n通过以上几个实验，我们可以看出，可燃物在氧气中燃烧比在空气中燃烧要剧烈。例如，硫在空气中燃烧发出微弱的淡蓝色火焰，而在氧气中燃烧得更旺，发出蓝紫色火焰。',notes=['P47比较现象归入本实验，但未回填P46空表。'])
add('铁丝在空气中加热与在氧气中燃烧',[[47,59,330,180,520],[47,393,465]],detail='【实验2-4】\n\n把两根光亮的细铁丝分别盘成螺旋状。取一根在酒精灯火焰上烧至红热，观察现象。另取一根，在其下端系一根火柴，点燃火柴，待火柴快燃尽时，插入盛有氧气的集气瓶中（预先放入一些水，如图2-13），观察现象。\n\n在空气中加热细铁丝时，铁丝红热，不能燃烧；但在氧气中点燃细铁丝可发生剧烈燃烧，火星四射。铁与氧气反应生成黑色的四氧化三铁（Fe₃O₄）固体。这个反应可以表示如下：\n\n铁 + 氧气 —点燃→ 四氧化三铁\n\n又如，某些在空气中不能燃烧的物质却可以在氧气中燃烧。这说明氧气的化学性质比较活泼，同时也说明，物质在空气中燃烧，实际上是与其中的氧气发生反应，由于空气中的氧气含量相对较低，在空气中燃烧不如在氧气中剧烈。')
add('化合反应、氧化反应与缓慢氧化',[[48,56,300,60,350]])
topic='课题3 制取氧气'
add('高锰酸钾分解制取氧气',[[50,182,410],[51,55,215]],detail='工业上一般采用分离空气的方法制取氧气。在实验室里，常采用高锰酸钾或过氧化氢分解等方法制取氧气。\n\n【实验2-5】\n\n如图2-14所示连接好装置。检查装置的气密性后，把少量高锰酸钾装入试管中，在试管口放一团棉花，用带有导管的橡胶塞塞紧试管，并把试管固定在铁架台上。将一个集气瓶盛满水，用玻璃片盖住瓶口，再将其与玻璃片一起倒立在盛水的水槽内。\n\n放一团棉花可以防止加热时试管内的粉末状物质进入导管。\n\n（1）加热试管，当导管口连续并比较均匀地放出气泡时，把导管口伸入盛满水的集气瓶，用排水法收集一瓶氧气。\n\n（2）把带有火星的木条插入集气瓶中，观察现象。\n\n|实验编号|现象|\n|---|---|\n|（1）||\n|（2）||\n\n高锰酸钾是一种暗紫色的固体，它受热时分解出氧气，同时还生成锰酸钾和二氧化锰。\n\n高锰酸钾 —加热→ 锰酸钾 + 二氧化锰 + 氧气')
add('工业分离空气制取氧气',[[51,278,425,50,350]])
add('过氧化氢分解探究与催化剂',[[51,455,655],[52,57,390],[53,50,200,180,520],[53,222,400]],detail='除了用高锰酸钾分解的方法制取氧气，在实验室里还常常用过氧化氢分解的方法制取氧气。过氧化氢溶液为无色透明液体，在医疗上可用于消毒防腐。在常温下过氧化氢可以分解放出氧气。\n\n探究：过氧化氢分解制取氧气的反应中二氧化锰的作用\n\n【问题】\n\n在使用过氧化氢溶液制取氧气时，通常加入少量二氧化锰，这是为什么呢？\n\n【实验】\n\n（1）在试管中加入5 mL 5%过氧化氢溶液，把带有火星的木条插入试管，观察现象。\n\n（2）向上述试管中加入少量二氧化锰，把带有火星的木条插入试管，观察现象（如图2-16）。\n\n仔细观察反应前后的二氧化锰。\n\n（3）待上述试管中没有现象发生时，重新加入过氧化氢溶液，并把带有火星的木条插入试管，观察现象。待试管中又没有现象发生时，再重复上述操作，观察现象。\n\n|实验编号|现象|\n|---|---|\n|（1）||\n|（2）||\n|（3）||\n\n在实验（1）中，带有火星的木条不能复燃，是因为过氧化氢在常温下分解缓慢，在较短时间内放出的氧气很少。在实验（2）中，木条复燃，是因为向过氧化氢溶液中加入少量二氧化锰使过氧化氢分解加速。这一反应可以表示如下：\n\n过氧化氢 —二氧化锰→ 水 + 氧气\n\n在实验（3）中，实验重复多次，每次只消耗了过氧化氢，二氧化锰好像永远用不完。如果在实验前用精密的天平称量二氧化锰的质量，实验后把二氧化锰洗净、干燥，再称量，你会发现它的质量没有发生变化。把它再加到过氧化氢溶液中，还可以加速过氧化氢分解。这种在化学反应里能改变其他物质的化学反应速率，而本身的质量和化学性质在反应前后都没有发生变化的物质叫作催化剂。催化剂在化学反应中所起的作用叫作催化作用。硫酸铜等物质对过氧化氢的分解也具有催化作用。\n\n催化剂在化工生产中有重要而广泛的应用，生产化肥、农药、化工原料等都要使用催化剂。',notes=['核心探究、证据、概念不拆入example。'])
add('分解反应与分类方法',[[53,518,660,185,520]])
add('实验探究的一般思路',[[54,90,345,75,350]])
add('合成氨与石油炼制中的催化剂',[[54,431,610,60,280]],detail='催化剂在化工生产中具有重要作用，大多数化工生产都有催化剂参与。例如，在合成氨工业中，即使在高温、高压下，氮气与氢气的化合反应仍然进行得十分缓慢，而以铁为主体的催化剂能使反应物在相对低的温度下较快发生反应。人类利用氮气和氢气合成氨，再生产含氮化肥，显著提高了农作物产量，有效保证了粮食安全。\n\n石油炼制过程需要使用高效催化剂生产汽油、煤油及其他石油化工产品。',notes=['同栏人物经历及评价排除。'])
(R/'selection.json').write_text(json.dumps(a,ensure_ascii=False,indent=2))
print(len(a))
